class OvertimeRecord extends DataClass implements Insertable<OvertimeRecord> {
  final int id;
  final int employeeId;
  final DateTime date;
  final double hours;
  final double rate;
  final double amount;
  final String? notes;
  final DateTime createdAt;

  /// المبلغُ عُدِّل يدوياً ⇒ لا يُعاد اشتقاقُه.
  ///
  /// السجلّاتُ القائمة تُهاجَر إلى `true`: قيمُها حُسبت بمقامٍ آخر، وإعادةُ
  /// حسابها تغيّر رواتبَ ماضية.
  final bool isManualAmount;
  const OvertimeRecord({
    required this.id,
    required this.employeeId,
