class Shift extends DataClass implements Insertable<Shift> {
  final int id;
  final DateTime startTime;
  final DateTime? endTime;
  final int userId;
  final int? branchId;
  final double openingBalance;
  final double? expectedCash;
  final double? actualCash;
  final double? variance;
  final String status;
  final String? notes;

  /// v151 — JSON snapshot of every figure the closing report was printed
  /// from, captured at close time.
  ///
  /// Reprinting a closed shift cannot be done by recomputation alone: the
  /// **actual** counted amounts are what the cashier typed, and only
  /// `actualCash` ever had a column — the bank and click counts were buried
  /// inside the free-text `notes` string. Anything reconstructed without them
  /// would disagree with the paper the cashier signed, which defeats the
  /// point of a reprint.
  ///
  /// NULL for shifts closed before this column existed; those fall back to
  /// recomputation and are labelled as such in the UI.
  final String? closingSnapshot;
  final String closingMethod;
  final DateTime createdAt;
  final String? globalId;
  final DateTime? lastModifiedAt;
  final DateTime? deletedAt;
  final String? originClientId;
  final int rowVersion;
  final int? posTerminalId;
  const Shift({
    required this.id,
    required this.startTime,
    this.endTime,
    required this.userId,
    this.branchId,
    required this.openingBalance,
    this.expectedCash,
    this.actualCash,
    this.variance,
    required this.status,
    this.notes,
    this.closingSnapshot,
    required this.closingMethod,
    required this.createdAt,
    this.globalId,
    this.lastModifiedAt,
    this.deletedAt,
    this.originClientId,
    required this.rowVersion,
    this.posTerminalId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['start_time'] = Variable<DateTime>(startTime);
    if (!nullToAbsent || endTime != null) {
      map['end_time'] = Variable<DateTime>(endTime);
    }
    map['user_id'] = Variable<int>(userId);
    if (!nullToAbsent || branchId != null) {
      map['branch_id'] = Variable<int>(branchId);
    }
    map['opening_balance'] = Variable<double>(openingBalance);
    if (!nullToAbsent || expectedCash != null) {
      map['expected_cash'] = Variable<double>(expectedCash);
    }
    if (!nullToAbsent || actualCash != null) {
      map['actual_cash'] = Variable<double>(actualCash);
    }
    if (!nullToAbsent || variance != null) {
      map['variance'] = Variable<double>(variance);
    }
    map['status'] = Variable<String>(status);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || closingSnapshot != null) {
      map['closing_snapshot'] = Variable<String>(closingSnapshot);
    }
    map['closing_method'] = Variable<String>(closingMethod);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || globalId != null) {
      map['global_id'] = Variable<String>(globalId);
    }
    if (!nullToAbsent || lastModifiedAt != null) {
      map['last_modified_at'] = Variable<DateTime>(lastModifiedAt);
    }
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    if (!nullToAbsent || originClientId != null) {
      map['origin_client_id'] = Variable<String>(originClientId);
    }
    map['row_version'] = Variable<int>(rowVersion);
    if (!nullToAbsent || posTerminalId != null) {
      map['pos_terminal_id'] = Variable<int>(posTerminalId);
    }
    return map;
  }

  ShiftsCompanion toCompanion(bool nullToAbsent) {
    return ShiftsCompanion(
      id: Value(id),
      startTime: Value(startTime),
      endTime: endTime == null && nullToAbsent
          ? const Value.absent()
          : Value(endTime),
      userId: Value(userId),
      branchId: branchId == null && nullToAbsent
          ? const Value.absent()
          : Value(branchId),
      openingBalance: Value(openingBalance),
      expectedCash: expectedCash == null && nullToAbsent
          ? const Value.absent()
