      actualCash: actualCash == null && nullToAbsent
          ? const Value.absent()
          : Value(actualCash),
      variance: variance == null && nullToAbsent
          ? const Value.absent()
          : Value(variance),
      status: Value(status),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
      closingSnapshot: closingSnapshot == null && nullToAbsent
          ? const Value.absent()
          : Value(closingSnapshot),
      closingMethod: Value(closingMethod),
      createdAt: Value(createdAt),
      globalId: globalId == null && nullToAbsent
          ? const Value.absent()
          : Value(globalId),
      lastModifiedAt: lastModifiedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(lastModifiedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      originClientId: originClientId == null && nullToAbsent
          ? const Value.absent()
          : Value(originClientId),
      rowVersion: Value(rowVersion),
      posTerminalId: posTerminalId == null && nullToAbsent
          ? const Value.absent()
          : Value(posTerminalId),
    );
  }

