  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Shift(
      id: serializer.fromJson<int>(json['id']),
      startTime: serializer.fromJson<DateTime>(json['startTime']),
      endTime: serializer.fromJson<DateTime?>(json['endTime']),
      userId: serializer.fromJson<int>(json['userId']),
      branchId: serializer.fromJson<int?>(json['branchId']),
      openingBalance: serializer.fromJson<double>(json['openingBalance']),
      expectedCash: serializer.fromJson<double?>(json['expectedCash']),
      actualCash: serializer.fromJson<double?>(json['actualCash']),
      variance: serializer.fromJson<double?>(json['variance']),
      status: serializer.fromJson<String>(json['status']),
      notes: serializer.fromJson<String?>(json['notes']),
      closingSnapshot: serializer.fromJson<String?>(json['closingSnapshot']),
      closingMethod: serializer.fromJson<String>(json['closingMethod']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      globalId: serializer.fromJson<String?>(json['globalId']),
      lastModifiedAt: serializer.fromJson<DateTime?>(json['lastModifiedAt']),
      deletedAt: serializer.fromJson<DateTime?>(json['deletedAt']),
      originClientId: serializer.fromJson<String?>(json['originClientId']),
      rowVersion: serializer.fromJson<int>(json['rowVersion']),
      posTerminalId: serializer.fromJson<int?>(json['posTerminalId']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'startTime': serializer.toJson<DateTime>(startTime),
      'endTime': serializer.toJson<DateTime?>(endTime),
      'userId': serializer.toJson<int>(userId),
      'branchId': serializer.toJson<int?>(branchId),
      'openingBalance': serializer.toJson<double>(openingBalance),
